// Test fixture dependency #2 (issue #89). Deliberately minimal and deliberately UNGRANTED: the
// tests that use it give it nothing in the policy, so every read below must be denied and
// recorded no matter what any OTHER package happens to be doing at the time.
//
// It exists because #89's worst property was not that the spawning package could read env — it
// is that the env gate was suspended PROCESS-WIDE, so a package with no grants at all read
// ungated for as long as someone else was inside a spawn. Proving that requires a second
// principal; fixture-dep cannot play both parts.
exports.read = (key) => process.env[key];

// The descriptor path too — the `get` trap's sibling hole (see shims/env.ts).
exports.readDescriptor = (key) => Object.getOwnPropertyDescriptor(process.env, key);

// Whole-environment harvest, the shape a real exfiltration payload uses.
exports.readAll = () => ({ ...process.env });

// ─────────────────────────────────────────────────────────────────────────────────────────────
// #90 — the composition matrix needs this package to hold NO grant of ANY kind, so that "does
// package A's privileged window open something for package B?" can be asked of every subsystem
// rather than only of `process.env`. Each helper below is one ungranted capability call; every
// one of them must be denied identically whether or not some other package happens to be inside
// a spawn, inside an authorized dgram send, or inside anything else.
// ─────────────────────────────────────────────────────────────────────────────────────────────

exports.readFile = (target) => require("fs").readFileSync(target, "utf8");

exports.connect = (host, port) => {
  const net = require("net");
  const s = net.connect({ host, port });
  s.on("error", () => {});
  s.destroy();
  return "connected";
};

exports.udpSend = (host, port) => {
  const dgram = require("dgram");
  const s = dgram.createSocket("udp4");
  const close = () => {
    try {
      s.close();
    } catch {}
  };
  try {
    s.send(Buffer.from("x"), port, host, close);
    return "sent";
  } catch (e) {
    close();
    throw e;
  }
};

exports.spawn = () => require("child_process").spawnSync(process.execPath, ["-e", ""]).status;

exports.runVm = (code) => require("vm").runInNewContext(code);
